#!/usr/bin/env bash
# CANNESS build contract v1: compile op_kernel/kernel.cpp and the universal
# host driver, then link one executable.
#
# This skeleton is operator-independent. Put operator logic in
# op_kernel/kernel.cpp and golden.h; do not edit this file per operator.
# The last stdout line MUST be the absolute executable path: the remote
# runner reads exactly that line.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$HERE"

CANN="${ASCEND_TOOLKIT_HOME:-/usr/local/Ascend/ascend-toolkit/latest}"
SOC_VERSION="{{SOC_VERSION}}"
BISHENG="${CANNESS_BISHENG:-bisheng}"

if ! command -v "$BISHENG" >/dev/null 2>&1; then
  echo "build.sh: bisheng not found; source set_env.sh before building" >&2
  exit 127
fi

INCLUDES=(
  -I"$HERE"
  -I"$CANN/aarch64-linux/tikcpp/tikcfw"
  -I"$CANN/aarch64-linux/tikcpp/tikcfw/impl"
  -I"$CANN/aarch64-linux/tikcpp/tikcfw/interface"
  -I"$CANN/aarch64-linux/asc/include"
  -I"$CANN/aarch64-linux/asc/include/basic_api"
  -I"$CANN/aarch64-linux/include"
  -I"$CANN/include"
)
FLAGS=(-x cce -std=c++17 "--cce-soc-version=$SOC_VERSION" --cce-soc-core-type=VecCore)

# Kernel object: GET_TILING_DATA / DTYPE_X come from the generic shim.
"$BISHENG" "${FLAGS[@]}" "${INCLUDES[@]}" -include "$HERE/canness_tiling.h" \
  -c op_kernel/kernel.cpp -o kernel.o

# Host driver: ACL allocation, launch, synchronisation and accuracy check.
"$BISHENG" "${FLAGS[@]}" "${INCLUDES[@]}" -include "$HERE/canness_tiling.h" \
  -c main.cpp -o main.o

# --allow-multiple-definition: both TUs include kernel_operator.h (the host
# driver through canness_tiling.h), and that header *defines* g_tilingKey in
# every TU, so a plain link fails with "duplicate symbol: g_tilingKey" on
# CANN 9.0.0. Nothing in this contract uses TILING_KEY, so the duplicate is
# harmless once the linker is allowed to pick one.
"$BISHENG" main.o kernel.o -o canness_run -Wl,--allow-multiple-definition \
  -L"$CANN/aarch64-linux/lib64" -L"$CANN/aarch64-linux/devlib" \
  -lascendcl -lruntime -lstdc++ -lpthread -ldl -lm \
  "-Wl,-rpath,$CANN/aarch64-linux/lib64:$CANN/aarch64-linux/devlib"

# run_once.sh and msprof-launched runs both use this path.
printf '%s\n' "$HERE/canness_run" > "$HERE/.canness-exe"
echo "build.sh: built $HERE/canness_run"
echo "$HERE/canness_run"
